import {roadmapDay,choicesFor,gateMet,supportIssue} from './roadmap.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(name,url)=>{try{const parsed=new URL(url);if(!['https:','http:'].includes(parsed.protocol))return '';return `<a href="${esc(parsed.href)}" target="_blank" rel="noopener noreferrer">${esc(name)} ↗</a>`;}catch{return '';}};
export const duration=b=>b.track==='rest'?'Off':b.dayRange?b.dayRange[0]+'–'+b.dayRange[1]+' min shared':b.minMinutes===b.maxMinutes?b.minMinutes+' min':b.minMinutes+'–'+b.maxMinutes+' min';
export function roadmapTitle(p){return p.roadmap&&!p.protectedDay?p.roadmap.blocks.map(b=>b.title).join(' → '):p.reason;}
export function renderRoadmapDay(p){
 const plan=p.roadmap;if(!plan)return '';
 return `<div class="roadmap-day"><p class="tiny-label">${esc(plan.phase.id)} · ${esc(plan.phase.title)}${plan.phase.optional?' · OPTIONAL':''} · ISO WEEK ${plan.week}</p><p class="small muted">Roadmap timeboxes and completion criteria. Tasks below are separate allocations; these blocks do not create study history.</p>${p.protectedDay?`<p class="quiet-notice">${esc(p.protectionReason||p.reason)} The independent roadmap yields to this protection.</p>`:''}${plan.blocks.map(b=>`<article class="roadmap-block"><h3>${esc(b.title)}</h3><p><b>${esc(duration(b))}</b>${b.dayRange?' for the whole Wednesday; ENSAM uses the remaining time.':''}</p><p>${esc(b.description)}</p><p><b>Done when:</b> ${esc(b.doneWhen)}</p>${!b.available?`<p class="muted">${esc(b.unavailableReason)}</p>`:''}${b.supportNotice?`<p>${esc(b.supportNotice)}</p>`:''}${b.links?.length?`<div class="quiet-links">${b.links.map(l=>link(l.title,l.url)).join(' ')}</div>`:''}${b.supports?.length?`<p class="small muted">Supports replace time in this block: ${b.supports.map(x=>esc(x.title)).join(' · ')}.</p>`:''}</article>`).join('')}${plan.notes.map(n=>`<p class="small muted">${esc(n)}</p>`).join('')}<p class="small muted">${esc('Exam peak: independent study may be zero. Keep university study time; move the milestone forward without doubled hours.')}</p></div>`;
}
export function renderRoadmapControls(s,day,today,catalog){
 const plan=roadmapDay(s,day);if(!plan||day<today)return '';
 const choices=choicesFor(s),phase=plan.phase.id;
 const supports=(s.planning.weeklyBlocks[phase]?.[new Date(day+'T12:00Z').getUTCDay()]||[]).flatMap(b=>b.supports||[]);
 const refs=[...new Map([...(catalog?.units||[]),...s.units].filter(u=>{const n=Number((u.unitRef.match(/(?:ch|chapter|lecture)\s*(\d+)/i)||[])[1]);return u.resourceId==='mml'?n>=8:u.resourceId==='cs229'&&(n>=1&&n<=9||n>=12&&n<=15||n===16&&/first half/i.test(u.unitRef+' '+u.heading));}).map(u=>[u.id,u])).values()];
 const gates=s.planning.roadmap.gates.filter(g=>g.phase===phase||phase==='Summer1'&&g.phase==='S2'||phase==='S4'&&g.id==='ml-evaluation');
 return `<details class="roadmap-controls"><summary>Roadmap choices and demonstrated gates</summary><form id="roadmap-choice-form" data-date="${day}"><p class="small muted">Gate confirmations describe demonstrated skills. They never mark a source task or chapter completed.</p><label class="checkbox"><input type="checkbox" name="summer1Enabled" ${choices.summer1Enabled?'checked':''}> Enable optional Summer 1 (July–August 2027)</label>${phase==='S1'?`<label class="checkbox"><input type="checkbox" name="mitTrialContinues" ${choices.mitTrialContinues?'checked':''}> I reviewed the two-week MIT trial against Stewart Ch. 15 and chose to continue</label>`:''}${phase==='S3'?`<label>Current question raised by Géron<input name="geronTopic" maxlength="500" value="${esc(choices.geronTopic||'')}" placeholder="The topic the Monday derivation should resolve"></label><label>One relevant reference (stage/review before using it)<select name="mathClinicUnitId"><option value="">Choose only for the current question</option>${refs.map(u=>`<option value="${esc(u.id)}" ${choices.mathClinicUnitId===u.id?'selected':''}>${esc(u.unitRef)} · ${esc(u.heading)}</option>`).join('')}</select></label>`:''}${phase==='S5'?`<label>ONE capstone branch<select name="capstoneBranch">${[['','Not chosen'],['A','A · LLM inference / batching'],['B','B · Sign language / industrial vision'],['C','C · Production ML']].map(([id,title])=>`<option value="${id}" ${choices.capstoneBranch===id?'selected':''}>${title}</option>`).join('')}</select></label><label>S5 elective<select name="elective">${[['','Not chosen'],['1','Option 1 · Informatics'],['2','Option 2 · AI & Connected Industry']].map(([id,title])=>`<option value="${id}" ${choices.elective===id?'selected':''}>${title}</option>`).join('')}</select></label><label class="checkbox"><input name="systemsSupportNeeded" type="checkbox" ${choices.systemsSupportNeeded?'checked':''}> The chosen branch needs systems support</label><label class="checkbox"><input name="capstoneTheoryNeeded" type="checkbox" ${choices.capstoneTheoryNeeded?'checked':''}> The capstone needs later UDL chapters</label>`:''}${phase==='S1'&&new Date(day+'T12:00Z').getUTCDay()===3?`<label class="checkbox"><input name="noEnsamWork" type="checkbox" ${choices.noEnsamDays?.includes(day)?'checked':''}> No current ENSAM work is available on ${day}; allow Goodrich/NeetCode fallback</label>`:''}${supports.length?`<label>Optional replacement for ${day}<select name="daySupport"><option value="">Keep the primary roadmap block</option>${supports.map(x=>{const issue=supportIssue(s,day,x);return `<option value="${esc(x.id)}" ${choices.daySupports?.[day]===x.id?'selected':''} ${issue?'disabled':''}>${esc(x.title)}${issue?' · '+esc(issue):''}</option>`;}).join('')}</select></label>`:''}${gates.length?`<div class="roadmap-gates">${gates.map(g=>`<label class="checkbox"><input name="gate" type="checkbox" value="${g.id}" ${gateMet(s,g.id)?'checked':''}> ${esc(g.title)}</label>`).join('')}</div>`:''}<label class="checkbox"><input name="examPeak" type="checkbox" ${s.overrides.some(o=>o.day===day&&o.kind==='ensam')?'checked':''}> ENSAM / exam peak on ${day}: zero independent study</label><button class="secondary" type="submit">Save roadmap choices</button></form></details>`;
}
